define('taoClientDiagnostic/tools/performances/tester',['jquery', 'lodash', 'i18n', 'async', 'context', 'helpers', 'taoClientDiagnostic/tools/stats', 'taoQtiItem/qtiItem/core/Loader', 'taoQtiItem/qtiCommonRenderer/renderers/Renderer', 'taoClientDiagnostic/tools/getConfig', 'taoClientDiagnostic/tools/getLabels', 'taoClientDiagnostic/tools/getStatus'], function ($, _, __, async, context, helpers, stats, Loader, Renderer, getConfig, getLabels, getStatus) {
  'use strict';
  var _second = 1000;
  var _defaultTimeout = 30 * _second;
  var _defaultOccurrencesCount = 10;
  var _defaultSamples = ['taoClientDiagnostic/tools/performances/data/sample1/', 'taoClientDiagnostic/tools/performances/data/sample2/', 'taoClientDiagnostic/tools/performances/data/sample3/'];
  var _defaults = {
    id: 'performances',
    optimal: 0.025,
    threshold: 0.25
  };
  var _thresholds = [{
    threshold: 0,
    message: __('Very slow performances'),
    type: 'error'
  }, {
    threshold: 33,
    message: __('Average performances'),
    type: 'warning'
  }, {
    threshold: 66,
    message: __('Good performances'),
    type: 'success'
  }];
  var _messages = [{
    title: __('Workstation performances'),
    status: __('Checking the performances...'),
    performancesMin: __('Minimum rendering time'),
    performancesMax: __('Maximum rendering time'),
    performancesAverage: __('Average rendering time')
  }];
  var _sampleBaseId = 'sample';
  function loadItem(data, done) {
    var qtiJsonFile = "".concat(data.url, "qti.json");
    var urlTokens = data.url.split('/');
    var extension = urlTokens[0];
    var fullpath = require.s.contexts._.config.paths[extension];
    var baseUrl = data.url.replace(extension, fullpath);
    var loader = new Loader();
    var renderer = new Renderer({
      baseUrl: baseUrl
    });
    if (renderer.getAssetManager) {
      renderer.getAssetManager().setData('baseUrl', baseUrl);
    }
    require(["json!".concat(qtiJsonFile)], function (itemData) {
      loader.loadItemData(itemData, function (item) {
        renderer.load(function () {
          var start = window.performance.now();
          item.setRenderer(this);
          var $container = $('<div>').appendTo('body');
          $container.append(item.render());
          item.postRender();
          $container.remove();
          var end = window.performance.now();
          var duration = (end - start) / _second;
          var result = {
            id: data.id,
            url: data.url,
            duration: duration
          };
          done(null, result);
        }, this.getLoadedClasses());
      });
    });
  }
  return function performancesTester(config) {
    var initConfig = getConfig(config, _defaults);
    var labels = getLabels(_messages, initConfig.level);
    var idx = 0;
    var _samples = _.map(!_.isEmpty(initConfig.samples) && initConfig.samples || _defaultSamples, sample => {
      idx++;
      return {
        id: _sampleBaseId + idx,
        url: sample,
        timeout: initConfig.timeout * 1000 || _defaultTimeout,
        nb: initConfig.occurrences || _defaultOccurrencesCount
      };
    });
    _samples[0].nb++;
    return {
      start(done) {
        var tests = [];
        _.forEach(_samples, data => {
          var cb = _.partial(loadItem, data);
          var iterations = data.nb || 1;
          while (iterations--) {
            tests.push(cb);
          }
        });
        async.series(tests, (err, measures) => {
          var decimals = 2;
          if (err && !measures.length) {
            throw err;
          }
          measures.shift();
          var results = stats(measures, 'duration', decimals);
          var status = this.getFeedback(results.average);
          var summary = this.getSummary(results);
          done(status, summary, results);
        });
      },
      get labels() {
        return labels;
      },
      getSummary(results) {
        return {
          performancesMin: {
            message: labels.performancesMin,
            value: "".concat(results.min, " s")
          },
          performancesMax: {
            message: labels.performancesMax,
            value: "".concat(results.max, " s")
          },
          performancesAverage: {
            message: labels.performancesAverage,
            value: "".concat(results.average, " s")
          }
        };
      },
      getFeedback(result) {
        var optimal = initConfig.optimal;
        var range = Math.abs(optimal - initConfig.threshold);
        var status = getStatus((range + optimal - result) / range * 100, _thresholds);
        status.title = labels.title;
        status.id = initConfig.id;
        return status;
      }
    };
  };
});
